from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
from scipy.spatial.distance import cdist
s='Cc1cc(C)cc(C)c1N=C(C)C=C(C)[N-]c1c(C)cc(C)cc1C'
cps='[C-]1(C)C(C)=C(C)C(C)=C1C'
orig=open('constrained.xyz').readlines();syms=[t.split()[0] for t in orig[2:]]
pos=np.array([[float(x) for x in t.split()[1:4]] for t in orig[2:]])
for sm, offset in [(s,0),(s,54),(cps,108),(cps,133)]:
 mol=Chem.AddHs(Chem.MolFromSmiles(sm)); conf=Chem.Conformer(mol.GetNumAtoms())
 for k in range(mol.GetNumAtoms()):conf.SetAtomPosition(k,pos[offset+k])
 mol.AddConformer(conf,assignId=True)
 props=AllChem.MMFFGetMoleculeProperties(mol)
 ff=AllChem.MMFFGetMoleculeForceField(mol,props,ignoreInterfragInteractions=False)
 for at in mol.GetAtoms():
  k=at.GetIdx()
  if at.GetSymbol()!='H':
   if at.GetSymbol()=='N':ff.MMFFAddPositionConstraint(k,0.015,450.0)
   else:ff.MMFFAddPositionConstraint(k,0.18,100.)
  else:ff.MMFFAddPositionConstraint(k,0.25,6.)
 ff.Initialize();r=ff.Minimize(maxIts=1200)
 print('MMFF',offset,'status',r,'energy',ff.CalcEnergy())
 pos[offset:offset+mol.GetNumAtoms()]=mol.GetConformer().GetPositions()
with open('mmff_fixed.xyz','w') as f:
 print(len(pos),file=f);print('Chelated In-In and In-Zn-Cp* structure, MMFF organic bond refinement',file=f)
 for el,p in zip(syms,pos): print('%s %.9f %.9f %.9f'%(el,*p),file=f)
for i,j in [(0,1),(0,2),(0,3),(1,2),(1,3)]:
 sl=[(0,54),(54,108),(108,133),(133,158)];l=sl[i];r=sl[j];d=cdist(pos[l[0]:l[1]],pos[r[0]:r[1]]);ix=np.unravel_index(np.argmin(d),d.shape);print('contact',i,j,d[ix],ix,syms[l[0]+ix[0]],syms[r[0]+ix[1]])
for i,j in [(9,10),(63,64),(158,9),(158,15),(159,63),(159,69),(158,160),(159,161)]:print('length',i,j,np.linalg.norm(pos[i]-pos[j]))
